import React from "react";
import { useTranslation } from "../../../contexts/LanguageContext";

type HealthState = "normal" | "degraded" | "error" | "unknown";

export interface HealthCardProps {
  state: HealthState;
  lastCheckedAt?: string | null; // ISO timestamp
  uptimePercent?: number | null; // 0-100
  onRefresh?: () => void;
  className?: string;
  loading?: boolean;
}

const COLOR_MAP: Record<HealthState, { bg: string; text: string; ring: string; icon: string }> = {
  normal: { bg: "bg-green-50 dark:bg-green-900/20", text: "text-green-700 dark:text-green-300", ring: "ring-green-400/40", icon: "fill-green-600" },
  degraded: { bg: "bg-yellow-50 dark:bg-yellow-900/20", text: "text-yellow-700 dark:text-yellow-300", ring: "ring-yellow-400/30", icon: "fill-yellow-600" },
  error: { bg: "bg-red-50 dark:bg-red-900/20", text: "text-red-700 dark:text-red-300", ring: "ring-red-400/30", icon: "fill-red-600" },
  unknown: { bg: "bg-slate-50 dark:bg-slate-800/30", text: "text-slate-700 dark:text-slate-300", ring: "ring-slate-400/20", icon: "fill-slate-600" },
};

function Icon({ state }: { state: HealthState }) {
  if (state === "normal") {
    return (
      <svg className="w-6 h-6" viewBox="0 0 24 24" aria-hidden>
        <circle cx="12" cy="12" r="10" className={COLOR_MAP[state].icon} />
        <path d="M8 12.5l2 2 5-5" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
      </svg>
    );
  }
  if (state === "degraded") {
    return (
      <svg className="w-6 h-6" viewBox="0 0 24 24" aria-hidden>
        <circle cx="12" cy="12" r="10" className={COLOR_MAP[state].icon} />
        <path d="M12 7v6" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" />
        <circle cx="12" cy="17" r="1" fill="#fff" />
      </svg>
    );
  }
  if (state === "error") {
    return (
      <svg className="w-6 h-6" viewBox="0 0 24 24" aria-hidden>
        <circle cx="12" cy="12" r="10" className={COLOR_MAP[state].icon} />
        <path d="M15 9L9 15M9 9l6 6" stroke="#fff" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  return (
    <svg className="w-6 h-6" viewBox="0 0 24 24" aria-hidden>
      <circle cx="12" cy="12" r="10" className={COLOR_MAP[state].icon} />
      <text x="12" y="15" textAnchor="middle" fontSize="10" fill="#fff">?</text>
    </svg>
  );
}

export default function HealthCard({
  state,
  lastCheckedAt,
  uptimePercent,
  onRefresh,
  className = "",
  loading = false,
}: HealthCardProps) {
  const { t } = useTranslation();
  const token = COLOR_MAP[state || "unknown"];
  const lastChecked = lastCheckedAt ? new Date(lastCheckedAt).toLocaleString() : "—";

  // Translation for state
  const stateLabel = t(`hub.healthCard.states.${state || "unknown"}`);

  if (loading) {
    return (
      <div className={`animate-pulse rounded-2xl p-4 ${className}`} role="status" aria-label="Loading health">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 rounded-full bg-slate-200 dark:bg-slate-700" />
          <div className="flex-1">
            <div className="h-4 bg-slate-200 dark:bg-slate-700 rounded w-3/4 mb-2" />
            <div className="h-3 bg-slate-200 dark:bg-slate-700 rounded w-1/2" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <article
      className={`rounded-2xl p-4 border border-transparent shadow-sm dark:shadow-none ${token.bg} ${className}`}
      aria-labelledby="ai-health-title"
      role="region"
    >
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-lg ${token.bg} ${token.ring} ring-1`}>
            <Icon state={state} />
          </div>
          <div>
            <h3 id="ai-health-title" className={`text-sm font-semibold ${token.text}`}>
              {t('hub.healthCard.title')}
            </h3>
            <p className="text-xs text-slate-600 dark:text-slate-300/70">{t('hub.healthCard.statusLabel')} <span className={`font-medium ${token.text}`}>{stateLabel}</span></p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {onRefresh && (
            <button
                onClick={onRefresh}
                aria-label={t('hub.healthCard.refresh')}
                className="inline-flex items-center gap-2 px-2 py-1 rounded-md text-xs bg-white/80 dark:bg-slate-700/60 hover:bg-white dark:hover:bg-slate-600 border border-slate-200 dark:border-slate-700"
            >
                {t('hub.healthCard.refresh')}
