const timeAgo = (isoTimestamp: string | null | undefined, t: (key: string, replacements?: any) => string): string => {
    if (!isoTimestamp) return '';
    const date = new Date(isoTimestamp);
    const now = new Date();
    const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (seconds < 60) return t('time.justNow');
    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return t('time.minutesAgo', { count: minutes });
    const hours = Math.floor(minutes / 60);
    if (hours < 24) return t('time.hoursAgo', { count: hours });
    const days = Math.floor(hours / 24);
    if (days < 30) return t('time.daysAgo', { count: days });
    const months = Math.floor(days / 30);
    if (months < 12) return t('time.monthsAgo', { count: months });
    const years = Math.floor(days / 365);
    return t('time.yearsAgo', { count: years });
};

export const RecentActivityCard: React.FC = () => {
    const [activity, setActivity] = useState<ActivityLog[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const { t } = useTranslation();

    useEffect(() => {
        const fetchActivity = async () => {
            setIsLoading(true);
            try {
                const data = await supabase.getRecentActivity();
                setActivity(data);
            } catch (error) {
                console.error("Error fetching recent activity:", error);
            } finally {
                setIsLoading(false);
            }
        };
        fetchActivity();
    }, []);

    return (
        <Card>
            <CardHeader><CardTitle>{t('hub.recentActivity.title')}</CardTitle></CardHeader>
            <CardContent>
                {isLoading ? (
                    <div className="space-y-4">
                        {[...Array(3)].map((_, i) => (
                             <div key={i} className="flex items-center space-x-3">
                                <Skeleton className="h-9 w-9 rounded-full" />
                                <div className="flex-1 space-y-2">
                                    <Skeleton className="h-3 w-3/4" />
                                    <Skeleton className="h-3 w-1/2" />
                                </div>
                            </div>
                        ))}
                    </div>
                ) : activity.length === 0 ? (
                    <p className="text-sm text-brand-text-secondary text-center py-4">{t('hub.recentActivity.empty')}</p>
                ) : (
                    <ul className="space-y-4">
                        {activity.map(log => (
                            <li key={log.timestamp + log.contact_name} className="flex items-start gap-3">
                                <Avatar name={log.contact_name} className="w-9 h-9 flex-shrink-0" />
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between items-center">
                                        <p className="font-semibold text-sm truncate">{log.contact_name}</p>
                                        <p className="text-xs text-brand-text-secondary flex-shrink-0 ml-2">{timeAgo(log.timestamp, t)}</p>
                                    </div>
                                    <p className="text-xs text-brand-text-secondary truncate">"{log.message_text}"</p>
                                </div>
                            </li>
                        ))}
                    </ul>
                )}
            </CardContent>
        </Card>
    );
};

