interface MessagePaneProps {
    instance: WhatsAppInstance;
    contact: WhatsAppContact;
    messages: WhatsAppMessage[];
    isLoading: boolean;
    onSendMessage: (text: string, imageBase64: string | null) => void;
    isSending: boolean;
    onLoadMore: () => void;
    hasMore: boolean;
    isLoadingMore: boolean;
    error: string | null;
    loadMoreError: string | null;
    onBack: () => void;
    suggestedTags: string[] | null;
    onSaveSuggestedTags: (tagsToSave: string[]) => void;
    onDismissSuggestions: () => void;
    onToggleDetailsPanel: () => void;
    isDetailsPanelOpen: boolean;
}

export const MessagePane: React.FC<MessagePaneProps> = ({ 
    instance,
    contact, 
    messages, 
    isLoading, 
    onSendMessage, 
    isSending, 
    onLoadMore, 
    hasMore, 
    isLoadingMore, 
    error, 
    loadMoreError, 
    onBack,
    suggestedTags,
    onSaveSuggestedTags,
    onDismissSuggestions,
    onToggleDetailsPanel,
    isDetailsPanelOpen
}) => {
    const { t } = useTranslation();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const prevScrollHeightRef = useRef(0);
    const shouldAutoScrollRef = useRef(true);

    const handleScroll = useCallback(() => {
        const container = scrollContainerRef.current;
        if (!container) return;

        const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 150;
        shouldAutoScrollRef.current = isNearBottom;

        if (container.scrollTop < 50 && hasMore && !isLoadingMore) {
            prevScrollHeightRef.current = container.scrollHeight;
            onLoadMore();
        }
    }, [hasMore, isLoadingMore, onLoadMore]);

    useEffect(() => {
        shouldAutoScrollRef.current = true;
    }, [contact]);

    useEffect(() => {
        const container = scrollContainerRef.current;
        container?.addEventListener('scroll', handleScroll);
        return () => container?.removeEventListener('scroll', handleScroll);
    }, [handleScroll]);

    useLayoutEffect(() => {
        const container = scrollContainerRef.current;
        if (!container) return;

        const didLoadMore = prevScrollHeightRef.current > 0;

        if (didLoadMore) {
            container.scrollTop = container.scrollHeight - prevScrollHeightRef.current;
            prevScrollHeightRef.current = 0;
        } else if (shouldAutoScrollRef.current) {
            container.scrollTo({ top: container.scrollHeight, behavior: "auto" });
        }
    }, [messages]);

    const renderContent = () => {
        if (isLoading) return <MessagePaneSkeleton />;
        if (error) return (
            <div className="flex justify-center items-center h-full text-center p-4">
                <div className="text-status-red bg-status-red/10 p-4 rounded-lg">
                    <p className="font-semibold">{t('common.error')}</p>
                    <p className="text-sm mt-1">{t('common.errorWithMessage', { message: error })}</p>
                </div>
            </div>
        );
        return (
            <div className="space-y-2">
                {messages.map(msg => <WhatsAppChatMessage key={msg.id} message={msg} />)}
            </div>
        );
    };

    return (
        <div className="flex-1 flex flex-col bg-brand-secondary w-full min-w-0">
            <header className="p-3 border-b border-brand-border flex-shrink-0 flex items-center gap-3 bg-brand-primary">
                <button onClick={onBack} className="md:hidden p-2 text-brand-text-secondary rounded-full hover:bg-brand-secondary -ml-2"><Icons.Icon id="back" className="h-5 w-5"/></button>
                <Avatar name={contact.contact_name} className="w-10 h-10 cursor-pointer" />
                <div className="flex-1 min-w-0">
                     <h3 className="font-semibold text-brand-text-primary truncate cursor-pointer">{contact.contact_name}</h3>
                     <p className="text-xs text-brand-text-secondary">{t('whatsapp.messagePane.online')}</p>
                </div>
                <div className="flex items-center gap-1 text-brand-text-secondary">
                    <Button variant="ghost" size="icon" className="h-9 w-9"><Icons.Icon id="search" className="h-5 w-5" /></Button>
                    <Button variant="ghost" size="icon" className="h-9 w-9" onClick={onToggleDetailsPanel}><Icons.Icon id="details" className="h-5 w-5" /></Button>
                </div>
            </header>
            <div ref={scrollContainerRef} className="flex-1 px-[calc(4%)] pt-4 pb-2 overflow-y-auto">
                {loadMoreError && (
                    <div className="text-center my-4"><p className="text-xs text-status-red">{loadMoreError}</p></div>
                )}
                {isLoadingMore && (
                    <div className="flex justify-center my-4"><p className="text-brand-text-secondary text-sm">{t('whatsapp.messagePane.loadingMore')}</p></div>
                )}
                {!hasMore && messages.length > 0 && !isLoadingMore && (
                    <div className="text-center my-4"><p className="text-brand-text-secondary text-xs">{t('whatsapp.messagePane.beginning')}</p></div>
                )}
                {renderContent()}
            </div>
            <MessageComposer onSendMessage={onSendMessage} isSending={isSending} />
        </div>
    );
};

import React, { useState } from 'react';
import { WhatsAppContact, Priority } from '../../types';
import { KanbanCard } from './KanbanCard';
import { Skeleton } from '../ui/Skeleton';
import { Button } from '../ui/Button';
import { useTranslation } from '../../contexts/LanguageContext';

const PlusIcon = (props: React.SVGProps<SVGSVGElement>) => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" {...props}><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg>;

interface KanbanColumnProps {
    title: string;
    contacts: WhatsAppContact[];
    onStageChange: (instanceId: string, contactName: string, newStage: string) => void;
    onView: (contact: WhatsAppContact) => void;
    onAddLead?: () => void;
    className?: string;
    isLoading: boolean;
    allStages: string[];
    onDueDateChange: (instanceId: string, contactName: string, newDueDate: string | null) => void;
    onPriorityChange: (instanceId: string, contactName: string, newPriority: Priority) => void;
}

export const KanbanColumn: React.FC<KanbanColumnProps> = ({ title, contacts, onStageChange, onView, onAddLead, className, isLoading, allStages, onDueDateChange, onPriorityChange }) => {
    const { t } = useTranslation();
    const [isDragOver, setIsDragOver] = useState(false);

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(true);
    };

    const handleDragLeave = () => {
        setIsDragOver(false);
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDragOver(false);
        const contactName = e.dataTransfer.getData('contactName');
        const instanceId = e.dataTransfer.getData('instanceId');
        const originalStage = e.dataTransfer.getData('originalStage');
        if (contactName && instanceId && originalStage !== title) {
            onStageChange(instanceId, contactName, title);
        }
    };

    // Translate the stage title for display
    const displayTitle = t(`crm.stages.${title.toLowerCase()}`);

    return (
        <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`w-72 flex-shrink-0 bg-brand-primary rounded-lg flex flex-col transition-colors duration-200 ${isDragOver ? 'bg-brand-accent/10' : ''}`}
        >
            <div className={`p-3 border-b-2 ${className || 'border-brand-border'} flex items-center justify-between`}>
                <div className="flex items-center gap-2">
                  <h3 className="font-semibold text-brand-text-primary text-sm uppercase tracking-wide">{displayTitle}</h3>
                  <span className="text-xs font-bold text-brand-text-secondary bg-brand-border/70 rounded-full px-2 py-0.5">{contacts.length}</span>
                </div>
                 {title === 'New' && onAddLead && (
                    <Button variant="ghost" size="icon" onClick={onAddLead} className="h-7 w-7 text-brand-text-secondary hover:text-brand-text-primary">
                        <PlusIcon className="h-4 w-4" />
                    </Button>
                )}
            </div>
            <div className="p-2 flex-1 overflow-y-auto space-y-2">
                {isLoading ? (
                    <div className="space-y-2">
                        <Skeleton className="h-32 w-full" />
                        <Skeleton className="h-32 w-full" />
                    </div>
                ) : contacts.length > 0 ? (
                    contacts.map(contact => <KanbanCard key={contact.contact_name} contact={contact} onStageChange={onStageChange} onView={onView} allStages={allStages} onDueDateChange={onDueDateChange} onPriorityChange={onPriorityChange} />)
                ) : !isDragOver && (
                    <div className="flex items-center justify-center h-full p-4 border-2 border-dashed border-brand-border/50 rounded-lg">
                        <p className="text-xs text-brand-text-secondary text-center">{t('crm.kanbanColumn.dragHelp')}</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default KanbanColumn;

