interface AIInsightCardProps {
    stats: DashboardStats | null;
    instances: WhatsAppInstance[];
}

const INSIGHT_ROTATION_INTERVAL_MS = 10000; // 10 seconds

export const AIInsightCard: React.FC<AIInsightCardProps> = ({ stats, instances }) => {
    const { t } = useTranslation();
    const { insights, isLoadingInsights, fetchInsights } = useAI();
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isFading, setIsFading] = useState(false);
    const timeoutRef = useRef<number | null>(null);

    useEffect(() => {
        if (stats) {
            fetchInsights(stats, instances);
        }
    }, [stats, instances, fetchInsights]);

    useEffect(() => {
        if (insights.length <= 1) return;

        const intervalId = setInterval(() => {
            setIsFading(true);

            timeoutRef.current = window.setTimeout(() => {
                setCurrentIndex(prevIndex => (prevIndex + 1) % insights.length);
                setIsFading(false);
            }, 300);

        }, INSIGHT_ROTATION_INTERVAL_MS);

        return () => {
            clearInterval(intervalId);
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
        };
    }, [insights]);


    return (
        <div className="xl:col-span-3 p-6 rounded-xl bg-gradient-to-br from-sky-900 via-slate-900 to-slate-900 text-white shadow-lg border border-sky-800/50 min-h-[116px]">
            <div className="flex items-start gap-4">
                <div className="p-2 bg-white/10 rounded-full">
                    <SparklesIcon className="w-6 h-6 text-sky-300" />
                </div>
                <div className="flex-1">
                    <h3 className="font-bold text-lg">{t('hub.insights.title')}</h3>
                    {isLoadingInsights ? (
                        <div className="space-y-2 mt-2">
                             <Skeleton className="h-4 w-3/4 bg-white/20" />
                             <Skeleton className="h-4 w-1/2 bg-white/20" />
                        </div>
                    ) : (
                        <p 
                            className={`text-sky-200 mt-1 transition-opacity duration-300 ease-in-out ${isFading ? 'opacity-0' : 'opacity-100'}`}
                            key={currentIndex}
                        >
                            {insights[currentIndex] || t('hub.insights.default')}
                        </p>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useRef } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/Card';
import { WhatsAppContact } from '../../types';
import { Skeleton } from '../ui/Skeleton';
import { useTranslation } from '../../contexts/LanguageContext';

const STAGES = ['New', 'Contacted', 'Proposal', 'Won', 'Lost'];
const stageColors: { [key: string]: string } = {
    'New': '#3b82f6', // blue-500
    'Contacted': '#8b5cf6', // violet-500
    'Proposal': '#f59e0b', // amber-500
    'Won': '#10b981', // emerald-500
    'Lost': '#ef4444', // red-500
};

interface ChartData {
    name: string;
    translatedName: string;
    count: number;
    color: string;
}

interface LeadsPipelineChartProps {
    contacts: WhatsAppContact[];
    isLoading: boolean;
}

export const LeadsPipelineChart: React.FC<LeadsPipelineChartProps> = ({ contacts, isLoading }) => {
    const { t } = useTranslation();
    const [hoveredBar, setHoveredBar] = useState<{data: ChartData, pos: {x: number, y: number}} | null>(null);
    const chartRef = useRef<SVGSVGElement>(null);

    const chartData = useMemo(() => {
        return STAGES.map(stage => {
            const count = contacts.filter(c => c.crm_stage === stage).length;
            return {
                name: stage,
                translatedName: t(`crm.stages.${stage.toLowerCase()}`),
                count,
                color: stageColors[stage] || '#9ca3af', // gray-400
            };
        });
    }, [contacts, t]);

    const maxCount = useMemo(() => {
        const max = Math.max(...chartData.map(d => d.count));
        return Math.max(5, Math.ceil(max / 5) * 5); // Round up to nearest 5, with a minimum of 5
    }, [chartData]);

    const handleMouseEnter = (e: React.MouseEvent<SVGRectElement>, data: ChartData) => {
        const rect = e.currentTarget.getBoundingClientRect();
        const svgRect = chartRef.current?.getBoundingClientRect();
        if (svgRect) {
            setHoveredBar({ data, pos: { x: rect.left - svgRect.left + rect.width / 2, y: rect.top - svgRect.top } });
        }
    };

    if (isLoading) {
        return (
            <Card>
                <CardHeader><CardTitle>{t('crm.pipelineChart.title')}</CardTitle></CardHeader>
                <CardContent>
                    <Skeleton className="h-64" />
                </CardContent>
            </Card>
        );
    }

    return (
        <Card>
            <CardHeader>
                <CardTitle>{t('crm.pipelineChart.title')}</CardTitle>
            </CardHeader>
            <CardContent>
                {contacts.length === 0 ? (
                    <div className="h-64 flex items-center justify-center bg-brand-secondary rounded-md">
                        <p className="text-brand-text-secondary text-sm">{t('crm.pipelineChart.noData')}</p>
                    </div>
                ) : (
                    <div className="relative">
                        <svg ref={chartRef} width="100%" height="256" viewBox="0 0 320 256">
                            {/* Y-Axis labels and grid lines */}
                            {[...Array(6)].map((_, i) => {
                                const y = 220 - (i * (200 / 5));
                                const value = (maxCount / 5) * i;
                                return (
                                    <g key={i} className="text-[10px] text-brand-text-secondary">
                                        <text x="20" y={y + 3} textAnchor="end" fill="currentColor">{value}</text>
                                        <line x1="25" x2="100%" y1={y} y2={y} className="stroke-brand-border" strokeWidth="1" />
                                    </g>
                                );
                            })}

                            {/* Bars and X-Axis labels */}
                            {chartData.map((data, index) => {
                                const barWidth = 30;
                                const barGroupWidth = 320 / STAGES.length;
                                const x = (barGroupWidth * index) + (barGroupWidth - barWidth) / 2;
                                const barHeight = data.count > 0 ? (data.count / maxCount) * 200 : 0;
                                return (
                                    <g key={data.name}>
                                        <rect
                                            x={x}
                                            y={220 - barHeight}
                                            width={barWidth}
                                            height={barHeight}
                                            fill={data.color}
                                            rx="4"
                                            ry="4"
                                            onMouseEnter={(e) => handleMouseEnter(e, data)}
                                            onMouseLeave={() => setHoveredBar(null)}
                                            className="transition-opacity duration-200 hover:opacity-80 cursor-pointer"
                                        >
                                            <animate attributeName="height" from="0" to={barHeight} dur="0.5s" fill="freeze" />
                                            <animate attributeName="y" from="220" to={220 - barHeight} dur="0.5s" fill="freeze" />
                                        </rect>
                                        {/* Truncate text for x-axis labels if too long */}
                                        <text x={x + barWidth / 2} y="240" textAnchor="middle" className="text-[10px] fill-brand-text-primary">
                                            {data.translatedName.length > 8 ? data.translatedName.substring(0, 7) + '..' : data.translatedName}
                                        </text>
                                    </g>
                                );
                            })}
                        </svg>
                        {hoveredBar && (
                            <div
                                className="absolute bg-brand-primary border border-brand-border rounded-md shadow-lg px-2 py-1 text-xs pointer-events-none transition-opacity duration-200"
                                style={{
                                    left: hoveredBar.pos.x,
                                    top: hoveredBar.pos.y,
                                    transform: `translate(-50%, -110%)`,
                                }}
                            >
                                <div className="font-bold">{hoveredBar.data.translatedName}</div>
                                <div>{t('crm.pipelineChart.tooltip.contacts')}: {hoveredBar.data.count}</div>
                            </div>
                        )}
                    </div>
                )}
            </CardContent>
        </Card>
    );
};

import React, { useMemo } from 'react';
