interface PipelineDistributionCardProps {
    contacts: WhatsAppContact[];
}

export const PipelineDistributionCard: React.FC<PipelineDistributionCardProps> = ({ contacts }) => {
    const { t } = useTranslation();

    const distribution = useMemo(() => {
        const total = contacts.length;
        if (total === 0) {
             return STAGES.map(stage => ({
                name: stage,
                translatedName: t(`crm.stages.${stage.toLowerCase()}`),
                count: 0,
                percentage: 0,
                color: stageColors[stage] || 'bg-gray-400',
            }));
        }
        return STAGES.map(stage => {
            const count = contacts.filter(c => c.crm_stage === stage).length;
            return {
                name: stage,
                translatedName: t(`crm.stages.${stage.toLowerCase()}`),
                count,
                percentage: total > 0 ? (count / total) * 100 : 0,
                color: stageColors[stage] || 'bg-gray-400',
            };
        });
    }, [contacts, t]);

    return (
        <Card>
            <CardHeader><CardTitle>{t('hub.pipelineDistribution.title')}</CardTitle></CardHeader>
            <CardContent>
                <div className="w-full h-4 bg-brand-secondary rounded-full flex overflow-hidden mb-4 shadow-inner">
                    {distribution.map(item => (
                        item.percentage > 0 && (
                            <div
                                key={item.name}
                                className={`${item.color} transition-all duration-500`}
                                style={{ width: `${item.percentage}%` }}
                                title={`${item.translatedName}: ${item.count} (${item.percentage.toFixed(1)}%)`}
                            />
                        )
                    ))}
                     {contacts.length === 0 && <div className="w-full h-full bg-brand-border" />}
                </div>
                <ul className="space-y-2 text-sm">
                    {distribution.map(item => (
                         <li key={item.name} className="flex justify-between items-center">
                            <div className="flex items-center gap-2">
                                <span className={`h-2.5 w-2.5 rounded-full ${item.color}`} />
                                <span className="text-brand-text-primary">{item.translatedName}</span>
                            </div>
                            <div className="font-semibold text-brand-text-primary">
                                {item.count}
                                <span className="ms-2 text-xs text-brand-text-secondary font-normal">({item.percentage.toFixed(0)}%)</span>
                            </div>
                        </li>
                    ))}
                </ul>
            </CardContent>
        </Card>
    );
};

