const LinkingStatusViewer = () => {
    const { t } = useTranslation();
    const messages = [
        t('whatsapp.connectModal.linkingStatus.init'),
        t('whatsapp.connectModal.linkingStatus.connect'),
        t('whatsapp.connectModal.linkingStatus.request'),
        t('whatsapp.connectModal.linkingStatus.wait'),
        t('whatsapp.connectModal.linkingStatus.prepare')
    ];
    const [index, setIndex] = useState(0);

    useEffect(() => {
        const intervalId = setInterval(() => {
            setIndex(prev => (prev + 1) % messages.length);
        }, 3000);
        return () => clearInterval(intervalId);
    }, [messages.length]);

    return (
        <div className="text-center">
            <svg className="animate-spin h-8 w-8 text-brand-accent mx-auto" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            <p key={index} className="mt-4 text-sm text-brand-text-secondary animate-in fade-in-0">{messages[index]}</p>
        </div>
    );
};


