  const [isLoading, setIsLoading] = useState(false);
  const [linkingCode, setLinkingCode] = useState<string | null>(null);
  const [newlyCreatedInstance, setNewlyCreatedInstance] = useState<WhatsAppInstance | null>(null);
  const { addToast } = useToast();
  const [isLinked, setIsLinked] = useState(false);

  useEffect(() => {
    // Reset state when modal is closed/reopened
    if (isOpen) {
      setStep(1);
      setAgentType(null);
      setPhoneNumber('');
      setCustomPrompt('');
      setIsLoading(false);
      setLinkingCode(null);
      setNewlyCreatedInstance(null);
      setIsLinked(false);
    }
  }, [isOpen]);

  useEffect(() => {
    if (!newlyCreatedInstance) return;

    const channel = supabase.channel(`linking-code-${newlyCreatedInstance.id}`);
    channel.on('postgres_changes', {
        event: 'INSERT',
        schema: 'public',
        table: 'whatsapp_linking_codes',
        filter: `instance_id=eq.${newlyCreatedInstance.id}`
    }, payload => {
        if (payload.new.code) {
            setLinkingCode(payload.new.code);
            setIsLoading(false);
        }
    })
    .on('postgres_changes', {
        event: 'UPDATE', schema: 'public', table: 'whatsapp_instances', filter: `id=eq.${newlyCreatedInstance.id}`
    }, payload => {
        if (payload.new.status === 'running') {
            setIsLinked(true);
            setNewlyCreatedInstance(whatsAppInstanceFromSupabase(payload.new));
        }
    })
    .subscribe();

    return () => {
        supabase.removeChannel(channel);
    };
  }, [newlyCreatedInstance]);

  const handleCreateInstance = async () => {
    setIsLoading(true);
    try {
        const instance = await supabase.addWhatsAppInstance(phoneNumber, customPrompt, agentType!);
        setNewlyCreatedInstance(instance);
        setStep(3);
    } catch (error: any) {
        addToast(error.message, { type: 'error' });
        setIsLoading(false);
    }
  };

  const renderStepContent = () => {
    switch(step) {
      case 1:
        return (
          <>
            <ModalHeader>
              <ModalTitle>{t('whatsapp.connectModal.step1.title')}</ModalTitle>
              <ModalDescription>{t('whatsapp.connectModal.step1.description')}</ModalDescription>
            </ModalHeader>
            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-4">
              <button onClick={() => { setAgentType('business'); setStep(2); }} className="p-6 border border-brand-border rounded-lg text-left hover:border-brand-accent hover:bg-brand-accent/5 transition-all">
                <BusinessIcon className="h-8 w-8 text-brand-accent mb-2" />
                <h3 className="font-semibold text-brand-text-primary">{t('whatsapp.connectModal.step1.businessTitle')}</h3>
                <p className="text-sm text-brand-text-secondary">{t('whatsapp.connectModal.step1.businessDesc')}</p>
              </button>
              <button onClick={() => { setAgentType('personal'); setStep(2); }} className="p-6 border border-brand-border rounded-lg text-left hover:border-brand-accent hover:bg-brand-accent/5 transition-all">
                <PersonIcon className="h-8 w-8 text-brand-accent mb-2" />
                <h3 className="font-semibold text-brand-text-primary">{t('whatsapp.connectModal.step1.personalTitle')}</h3>
                <p className="text-sm text-brand-text-secondary">{t('whatsapp.connectModal.step1.personalDesc')}</p>
              </button>
            </div>
            <ModalFooter><Button variant="outline" onClick={onClose}>{t('whatsapp.connectModal.buttons.cancel')}</Button></ModalFooter>
          </>
        );
      case 2:
        return (
          <>
            <ModalHeader>
              <ModalTitle>{agentType === 'business' ? t('whatsapp.connectModal.step2.businessTitle') : t('whatsapp.connectModal.step2.personalTitle')}</ModalTitle>
              <ModalDescription>{t('whatsapp.connectModal.step2.description')}</ModalDescription>
            </ModalHeader>
            <div className="p-6 space-y-4">
               <div>
                <label className="text-sm font-medium">{t('whatsapp.connectModal.step2.phoneLabel')}</label>
                <Input value={phoneNumber} onChange={e => setPhoneNumber(e.target.value)} placeholder={t('whatsapp.connectModal.step2.phonePlaceholder')} className="mt-1" />
              </div>
              <div>
                 <label className="text-sm font-medium">{t('whatsapp.connectModal.step2.aiLabel')}</label>
                 <PromptGenerator 
                    useCase={agentType!}
                    onPromptGenerated={(prompt) => setCustomPrompt(prompt)}
                    onCancel={() => setStep(1)}
                 />
              </div>
            </div>
             <ModalFooter>
                <Button variant="outline" onClick={() => setStep(1)}>{t('whatsapp.connectModal.buttons.back')}</Button>
                <Button onClick={handleCreateInstance} disabled={isLoading || !phoneNumber || !customPrompt}>
                    {isLoading ? t('whatsapp.connectModal.step2.generating') : t('whatsapp.connectModal.step2.generateCode')}
                </Button>
            </ModalFooter>
          </>
        );
      case 3:
        if (isLinked && newlyCreatedInstance) {
            return (
                 <>
                    <ModalHeader>
                        <ModalTitle className="text-status-green">{t('whatsapp.connectModal.step3.successTitle')}</ModalTitle>
                        <ModalDescription>{t('whatsapp.connectModal.step3.successDesc', { phoneNumber: newlyCreatedInstance.phoneNumber })}</ModalDescription>
                    </ModalHeader>
                    <div className="p-10 text-center">
                        <CheckCircleIcon className="h-16 w-16 text-status-green mx-auto" />
                    </div>
                    <ModalFooter>
                        <Button variant="outline" onClick={onClose}>{t('whatsapp.connectModal.buttons.done')}</Button>
                        <Button onClick={() => onLinkSuccess(newlyCreatedInstance)}>{t('whatsapp.connectModal.buttons.viewChats')}</Button>
                    </ModalFooter>
                </>
            );
        }
        return (
          <>
            <ModalHeader>
              <ModalTitle>{t('whatsapp.connectModal.step3.linkTitle')}</ModalTitle>
              <ModalDescription>{t('whatsapp.connectModal.step3.linkDesc', { phoneNumber: phoneNumber })}</ModalDescription>
            </ModalHeader>
            <div className="p-10 text-center">
              {isLoading && (
                 <LinkingStatusViewer />
              )}
              {linkingCode && (
                <>
                    <p className="text-sm text-brand-text-secondary">{t('whatsapp.connectModal.step3.codeLabel')}</p>
                    <div className="my-4 text-3xl font-bold tracking-widest text-brand-text-primary bg-brand-secondary p-4 rounded-lg">
                        {linkingCode}
                    </div>
                    <p className="text-xs text-brand-text-secondary max-w-xs mx-auto">{t('whatsapp.connectModal.step3.instructions')}</p>
                </>
              )}
               {!isLoading && !linkingCode && (
                   <LinkingStatusViewer />
               )}
            </div>
            <ModalFooter>
              <Button variant="outline" onClick={onClose}>{t('whatsapp.connectModal.buttons.close')}</Button>
            </ModalFooter>
          </>
        )
      default: return null;
    }
  };

  return (
    <Modal open={isOpen} onOpenChange={onClose}>
      <ModalContent>{renderStepContent()}</ModalContent>
    </Modal>
  );
};

export default AddInstanceModal;

