                type: Type.OBJECT,
                properties: {
                  type: { type: Type.STRING, enum: ['new_contact_message', 'contact_replied', 'crm_stage_changed', 'tag_added', 'message_contains_keyword', 'priority_changed'] },
                  config: { 
