              },
              actions: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    type: { type: Type.STRING, enum: ['send_whatsapp_message', 'add_tag', 'change_crm_stage', 'wait'] },
                    config: {
                      type: Type.OBJECT,
                      properties: {
